<script>
  import { onMount } from 'svelte';
  import { attacks, defaultProject, partyOptions, provenance } from '../lib/combat/data.js';
  import { damage, simulate, pyroResonance } from '../lib/combat/engine.js';
  import { evaluate, validateProject } from '../lib/combat/project.js';
  let project = defaultProject();
  let selected = 'charged', addKind = 'charged', message = '', pending = null, baseline = null;
  const key = 'paimon-combat-v1';
  const fields = [ ['weaponAtk', 'Weapon base ATK'], ['atkPercent', 'Equipment ATK %'], ['flatAtk', 'Flat ATK'], ['critRate', 'Total CRIT Rate %'], ['critDamage', 'Total CRIT DMG %'], ['pyroBonus', 'Pyro DMG Bonus %'], ['physicalBonus', 'Physical DMG Bonus %'], ['em', 'Elemental Mastery'] ];
  const enemyFields = [['level', 'Enemy level'], ['resistance', 'Hit resistance %'], ['defenseReduction', 'DEF reduction %'], ['defenseIgnore', 'DEF ignore %']];
  const fmt = n => new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format(n);
  $: result = evaluate(project, damage, simulate, selected);
  $: comparison = baseline ? evaluate(baseline, damage, simulate, selected) : null;
  $: resonance = pyroResonance(project.party);
  $: chart = result.rotation ? `0,150 ${result.rotation.events.map(e => `${e.end / result.rotation.duration * 600},${150 - e.total / Math.max(1, result.rotation.total) * 140}`).join(' ')}` : '';
  function save() { try { localStorage.setItem(key, JSON.stringify(validateProject(project))); message = 'Saved on this browser.'; } catch (e) { message = e.message; } }
  function restore() { try { const data = localStorage.getItem(key); if (!data) throw new Error('No saved project in this browser.'); pending = validateProject(JSON.parse(data)); message = 'Saved project ready to preview.'; } catch (e) { message = e.message; } }
  function exportProject() {
    try { const blob = new Blob([JSON.stringify(validateProject(project), null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'paimon-combat.json'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); message = 'Project exported.'; } catch (e) { message = e.message; }
  }
  async function importProject(event) { pending = null; try { const file = event.target.files[0]; if (!file) return; if (file.size > 100000) throw new Error('Please use a JSON file smaller than 100 KB.'); pending = validateProject(JSON.parse(await file.text())); message = 'Import validated. Review the preview before applying.'; } catch (e) { message = `Import rejected: ${e.message}`; } event.target.value = ''; }
  function move(i, delta) { const actions = [...project.actions]; [actions[i], actions[i + delta]] = [actions[i + delta], actions[i]]; project = { ...project, actions }; }
  function pin() { try { baseline = validateProject(project); message = 'Comparison baseline captured. Edit your build to compare.'; } catch (e) { message = e.message; } }
  onMount(() => { message = 'Sample equipment values — replace them with your own build.'; });
</script>

<svelte:head><title>Combat Workbench · Paimon.moe</title><meta name="description" content="An explainable Amber damage calculator with a transparent rotation model." /></svelte:head>
<div class="workbench pt-20 lg:ml-64 lg:pt-8 px-4 md:px-8">
  <header><div><p class="eyebrow">PAIMON.MOE / THEORYCRAFTING</p><h1>Combat workbench</h1><p>Build a hypothesis. Inspect every number.</p></div><span class="badge">Amber reference slice · v1</span></header>
  <div class="toolbar"><button on:click={save} disabled={!!result.error}>Save locally</button><button on:click={restore}>Restore</button><button on:click={exportProject} disabled={!!result.error}>Export JSON</button><label class="upload">Import JSON<input type="file" accept=".json,application/json" on:change={importProject} /></label><button on:click={pin} disabled={!!result.error}>Capture comparison</button></div>
  <p class="notice" role="status">{message}</p>
  {#if pending}<section class="import-preview"><h2>Import preview</h2><p>{pending.name} · {pending.actions.length} actions · {pending.cycles} cycle(s) · weapon ATK {pending.build.weaponAtk}</p><p>Applying replaces the current editor. Your saved project stays unchanged until you save.</p><button on:click={() => { project = pending; pending = null; message = 'Import applied.'; }}>Apply project</button><button on:click={() => pending = null}>Cancel</button></section>{/if}
  <div class="workspace">
    <section class="panel build">
      <div class="identity"><img src="/images/characters/amber.png" alt="Amber" width="80" height="80" /><div><p class="eyebrow">PYRO / BOW</p><h2>Amber</h2><p>Level 90 · Ascension 6 · C0 · Talents 9</p></div></div>
      <label>Study name<input bind:value={project.name} maxlength="120" /></label>
      <h3>Equipment contributions</h3><p class="muted">Manual aggregate inputs. ATK % excludes Amber’s built-in 24% ascension bonus. CRIT values include base stats. Weapon passives and artifact sets are not inferred.</p>
      <div class="fields">{#each fields as [id, label]}<label>{label}<input type="number" min="0" step="0.1" bind:value={project.build[id]} /></label>{/each}</div>
      <h3>Enemy</h3><div class="fields">{#each enemyFields as [id, label]}<label>{label}<input type="number" step="0.1" bind:value={project.enemy[id]} /></label>{/each}</div><p class="muted">Resistance is shared across the selected hits. Use matching physical and Pyro resistance for mixed rotations.</p>
    </section>
    <div class="results">
      <section class="panel"><div class="section-head"><h2>Damage inspection</h2><select aria-label="Inspect attack" bind:value={selected}>{#each Object.entries(attacks).filter(([id]) => id !== 'wait') as [id, attack]}<option value={id}>{attack.name}</option>{/each}</select></div>
      {#if result.error}<p class="error" role="alert">{result.error}</p>{:else}
        <div class="metrics"><div><span>Expected damage</span><strong>{fmt(result.hit.expected)}</strong></div><div><span>Non-critical</span><strong>{fmt(result.hit.nonCrit)}</strong></div><div><span>Critical</span><strong>{fmt(result.hit.critical)}</strong></div></div>
        <p class="muted">Per action, evaluated at 0s. Fiery Rain is the full burst total and includes Amber’s +10% burst CRIT Rate passive.</p>
        <details open><summary>Follow the calculation</summary><div class="formula">ATK × talent × DMG bonus × defense × resistance × reaction × expected CRIT</div><dl>{#each [['Total ATK', result.hit.atk], ['Talent multiplier', result.hit.talent], ['DMG bonus multiplier', result.hit.bonus], ['Defense multiplier', result.hit.defense], ['Resistance multiplier', result.hit.resistance], ['Reaction multiplier', result.hit.reaction], ['Expected CRIT multiplier', 1 + result.hit.critRate * project.build.critDamage / 100]] as [label, value]}<div><dt>{label}</dt><dd>{value.toFixed(4)}</dd></div>{/each}</dl></details>
        {#if comparison?.hit}<p class="comparison">Against captured build: <b>{fmt(result.hit.expected - comparison.hit.expected)}</b> damage ({comparison.hit.expected ? fmt((result.hit.expected / comparison.hit.expected - 1) * 100) + '%' : 'baseline is zero'}).</p>{/if}
      {/if}</section>
      <section class="panel"><h2>Party & conditions</h2><div class="party">{#each project.party as member, i}<label>Slot {i + 1}<select disabled={i === 0} bind:value={project.party[i]}><option value="">Empty</option>{#each Object.entries(partyOptions) as [id, [name, element]]}<option value={id} disabled={project.party.includes(id) && member !== id}>{name} · {element}</option>{/each}</select></label>{/each}</div>
        <p class="effect"><b>Fervent Flames · {resonance ? 'Active' : 'Inactive'}</b><span>+25% ATK. Requires a full, unique four-character party with two Pyro members.</span></p><p class="muted">Teammates only determine Pyro resonance in this slice. Their damage, abilities, and other resonances are unsupported.</p>
        <label>Charged-shot reaction assumption<select bind:value={project.reaction}><option value="none">No reaction</option><option value="vaporize">Vaporize · supplied Hydro aura</option><option value="melt">Melt · supplied Cryo aura</option></select></label><p class="muted">Assumes the chosen aura exists for every charged shot. Aura supply and depletion are not simulated. Burst and normal attacks remain unamplified.</p>
        <label class="check"><input type="checkbox" bind:checked={project.buff.enabled} />Manual ATK buff window</label><div class="fields three"><label>ATK %<input type="number" bind:value={project.buff.atkPercent} /></label><label>Start (s)<input type="number" min="0" step="0.1" bind:value={project.buff.start} /></label><label>End (s)<input type="number" min="0" step="0.1" bind:value={project.buff.end} /></label></div><p class="muted">User assumption, not an automatically verified character effect. Applied at action start; burst stats snapshot there.</p>
      </section>
    </div>
  </div>
  <section class="panel rotation"><div class="section-head"><div><p class="eyebrow">SEQUENCE LAB</p><h2>Rotation model</h2></div><div class="toolbar"><select aria-label="Action to add" bind:value={addKind}>{#each Object.entries(attacks) as [id, attack]}<option value={id}>{attack.name}</option>{/each}</select><button disabled={project.actions.length >= 100} on:click={() => project.actions = [...project.actions, addKind]}>Add action</button></div></div>
    <div class="fields"><label>Initial energy (0–40)<input type="number" min="0" max="40" bind:value={project.initialEnergy} /></label><label>Consecutive cycles (1–10)<input type="number" min="1" max="10" bind:value={project.cycles} /></label></div>
    <ol class="actions">{#each project.actions as kind, i}<li><span>{i + 1}. {attacks[kind].name} <small>{attacks[kind].duration.toFixed(2)}s</small></span><div><button aria-label={`Move action ${i + 1} earlier`} disabled={i === 0} on:click={() => move(i, -1)}>↑</button><button aria-label={`Move action ${i + 1} later`} disabled={i === project.actions.length - 1} on:click={() => move(i, 1)}>↓</button><button aria-label={`Duplicate action ${i + 1}`} disabled={project.actions.length >= 100} on:click={() => project.actions = [...project.actions.slice(0, i + 1), kind, ...project.actions.slice(i + 1)]}>Copy</button><button aria-label={`Remove action ${i + 1}`} disabled={project.actions.length === 1} on:click={() => project.actions = project.actions.filter((_, j) => i !== j)}>×</button></div></li>{/each}</ol>
    <p class="notice">Approximate action-level model: assumes every hit connects at close range, no weak points, no particles or energy regeneration. Fiery Rain uses a 3.2s modeled window; damage is booked at each action’s end. Failed actions occupy their window but deal zero damage. This is not a frame-accurate or sustained team-DPS prediction.</p>
    {#if result.rotation}<div class="metrics"><div><span>Modeled total</span><strong>{fmt(result.rotation.total)}</strong></div><div><span>Damage / modeled second</span><strong>{fmt(result.rotation.dps)}</strong></div><div><span>Duration</span><strong>{fmt(result.rotation.duration)}s</strong></div><div><span>Final energy</span><strong>{result.rotation.energy}</strong></div></div>
      <p class:error={!result.rotation.feasible}>{result.rotation.feasible ? 'Cooldown and initial-energy checks pass under the stated assumptions.' : 'Sequence infeasible. Failed actions are excluded from damage.'}</p>
      {#each result.rotation.warnings as warning}<p class="error">{warning}</p>{/each}
      <figure><figcaption>Cumulative modeled damage · 0–{fmt(result.rotation.duration)} seconds · 0–{fmt(result.rotation.total)} damage</figcaption><svg viewBox="0 0 600 160" role="img" aria-label="Cumulative damage chart; exact values are available in the combat log below"><path d="M0 150H600 M0 80H600 M0 10H600" stroke="#414762" fill="none"/><polyline points={chart} fill="none" stroke="#e9bf73" stroke-width="3" /></svg></figure>
      <details><summary>Combat log · accessible chart data</summary><div class="table-wrap"><table><thead><tr><th>Cycle</th><th>Start–end</th><th>Action</th><th>Damage</th><th>Cumulative</th><th>Buff</th><th>Status</th></tr></thead><tbody>{#each result.rotation.events as event}<tr><td>{event.cycle}</td><td>{event.start.toFixed(2)}–{event.end.toFixed(2)}s</td><td>{attacks[event.kind].name}</td><td>{fmt(event.damage)}</td><td>{fmt(event.total)}</td><td>{event.buffActive ? 'Active' : 'Inactive'}</td><td>{event.reason || 'OK'}</td></tr>{/each}</tbody></table></div></details>
    {/if}
  </section>
  <section class="panel sources"><h2>Coverage & provenance</h2><p>Ruleset: {provenance.ruleset} · Reviewed {provenance.reviewed}. Game version: {provenance.gameVersion}.</p><p>Supported: Amber level 90/C0/talent 9 normal first hit, charged shot, and full burst; expected CRIT; defense; resistance; charged-shot Melt/Vaporize; Pyro resonance; manual timed ATK buff.</p><p>Not yet supported: full equipment database, five-slot artifact editing, other characters’ damage, skill summons, automatic aura/ICD, particles, optimizer, GOOD/account imports, Lunar or Hexerei effects. JSON imports accept this workbench’s own versioned export only.</p><ul>{#each provenance.sources as source}<li><a href={source} target="_blank" rel="noreferrer">{source.replace('https://library.keqingmains.com/', 'KQM / ')}</a></li>{/each}</ul></section>
</div>

<style>
  .workbench { --surface:#292e4d; --line:#48516d; --muted:#bcc4d9; --accent:#e9bf73; color:#f5f3ed; max-width:1800px; }
  header,.section-head,.identity,.toolbar { display:flex; align-items:center; gap:1rem; flex-wrap:wrap; }
  header,.section-head { justify-content:space-between; } header { margin-bottom:1.5rem; } h1 { font-size:2.25rem; font-weight:700; letter-spacing:-.04em; } h2 { font-size:1.35rem; font-weight:600; } h3 { font-weight:600; margin:1.5rem 0 .75rem; }
  p { line-height:1.65; } .eyebrow { font-size:.7rem; letter-spacing:.16em; color:var(--accent); } .badge { border:1px solid var(--line); padding:.5rem .75rem; border-radius:4px; font-size:.8rem; }
  .toolbar { gap:.5rem; } button,.upload { background:#39415f; border:1px solid #66708d; padding:.5rem .75rem; border-radius:4px; cursor:pointer; font-size:.85rem; } button:hover,.upload:hover { background:#465270; } button:disabled { opacity:.45; cursor:not-allowed; } :global(.workbench :focus-visible) { outline:3px solid #e9bf73; outline-offset:3px; }
  .upload { position:relative; overflow:hidden; display:inline-block; margin:0; } .upload input { position:absolute; inset:0; opacity:0; cursor:pointer; width:100%; } .upload:focus-within { outline:3px solid var(--accent); }
  .notice { background:#252a42; border-left:3px solid var(--accent); padding:.75rem 1rem; margin:1rem 0; color:#e0d8c8; font-size:.85rem; }
  .workspace { display:grid; grid-template-columns:minmax(260px, .85fr) minmax(0,1.5fr); gap:1rem; align-items:start; }.panel,.import-preview { padding:1.5rem; background:var(--surface); border:1px solid var(--line); border-radius:6px; margin-bottom:1rem; min-width:0; }.identity { margin-bottom:1.5rem; }.identity img { background:#715345; border-radius:4px; }.identity p:not(.eyebrow) { font-size:.8rem; color:var(--muted); }
  label { display:flex; flex-direction:column; gap:.4rem; font-size:.8rem; color:var(--muted); margin-top:.75rem; } input,select { width:100%; background:#1d223b; border:1px solid #69728e; color:#f5f3ed; padding:.6rem .75rem; border-radius:4px; min-width:0; font-size:.9rem; } .section-head select,.toolbar select { width:auto; max-width:100%; }.fields { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:.75rem; }.three { grid-template-columns:repeat(3,minmax(0,1fr)); }.muted { color:var(--muted); font-size:.8rem; margin:.75rem 0; }
  .metrics { display:flex; flex-wrap:wrap; gap:1.5rem; margin:1.5rem 0; }.metrics span { display:block; font-size:.75rem; color:var(--muted); }.metrics strong { display:block; font-size:1.8rem; font-variant-numeric:tabular-nums; color:var(--accent); }.metrics div:first-child strong { font-size:2.25rem; }.formula { font-size:.8rem; line-height:1.7; padding:.75rem 0; color:var(--muted); } dl div { display:flex; justify-content:space-between; gap:1rem; padding:.4rem 0; border-bottom:1px solid var(--line); font-size:.85rem; } dd { font-variant-numeric:tabular-nums; } summary { cursor:pointer; padding:.75rem 0; } .party { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:.75rem; }.effect { border-left:3px solid var(--accent); padding-left:1rem; margin-top:1rem; }.effect span { display:block; font-size:.85rem; color:var(--muted); }.check { flex-direction:row; align-items:center; }.check input { width:auto; }.error { color:#ffb6ad; padding:.5rem 0; }.comparison { margin-top:1rem; color:var(--accent); }.actions { margin:1rem 0; }.actions li { display:flex; align-items:center; justify-content:space-between; gap:.75rem; border-bottom:1px solid var(--line); padding:.65rem 0; }.actions li div { display:flex; gap:.25rem; }.actions small { color:var(--muted); margin-left:.5rem; } figure { margin:1rem 0; } figcaption { font-size:.8rem; color:var(--muted); } svg { width:100%; max-height:240px; margin-top:1rem; }.table-wrap { overflow-x:auto; } table { width:100%; text-align:left; font-size:.8rem; } th,td { padding:.6rem; border-bottom:1px solid var(--line); white-space:nowrap; }.sources p,.sources a { font-size:.85rem; color:var(--muted); }.sources p { margin:.75rem 0; }.sources a { color:var(--accent); overflow-wrap:anywhere; } .sources ul { list-style:disc; padding-left:1.25rem; }
  @media(max-width:1100px) { .workspace { grid-template-columns:1fr; } } @media(max-width:480px) { .panel { padding:1rem; } h1 { font-size:1.8rem; }.party,.three { grid-template-columns:1fr; }.actions li { align-items:start; flex-direction:column; }.metrics { gap:1rem; } }
</style>
